// n8n Code node: "Seed sources"
// The crawl targets. Adding a site = one more object here plus a table layout the
// "Parse lender tables" node understands (header: Bank/Lender | Interest Rate | ...).
// `single_product`: a lender's OWN site, one product per page, so the page is both the list
// and the detail page (no table of lenders). Official-site data is the most authoritative.
// NOTE: policybazaar.com/personal-loan/* redirects to paisabazaar.com (same group), so it
// is not a distinct source and is deliberately not listed.
return [
  { json: { source_site: 'paisabazaar', list_url: 'https://www.paisabazaar.com/personal-loan/interest-rates/' } },
  { json: { source_site: 'bankbazaar', list_url: 'https://www.bankbazaar.com/personal-loan.html' } },
  {
    json: {
      source_site: 'bajajfinserv',
      list_url: 'https://www.bajajfinserv.in/personal-loan',
      single_product: 'Bajaj Finance Personal Loan',
    },
  },
];

// n8n Code node: "Parse lender tables"  (mode: Run Once for All Items)
//
// Input : one item per list page, from "Fetch list page" (json.data = page HTML).
// Output: one item per lender row found in the rate tables:
//         { source_site, product_name, interest_rate, rate_text, max_amount_text,
//           tenure_text, fee_text, detail_url }
//
// Deterministic on purpose: the rate tables are clean HTML, so an LLM here would only
// add cost and the chance of hallucinated numbers.

const MAX_LENDERS_PER_SITE = 40; // safety valve against a layout change exploding the crawl
const out = [];

const ENT = { amp: '&', nbsp: ' ', quot: '"', apos: "'", lt: '<', gt: '>', rupee: '₹' };
const decode = (s) =>
  s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&([a-z]+);/gi, (m, n) => (ENT[n.toLowerCase()] !== undefined ? ENT[n.toLowerCase()] : m));
const text = (h) => decode(h.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const stripNoise = (h) => h.replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, '');

// "9.99% onwards*" -> 9.99 ; "10.00% - 30.50%" -> 10 (lowest advertised) ;
// "1.25% per month" -> 15 (annualised, simple) ; "Up to 36% p.a." -> 36
function parseRate(t) {
  const m = t.match(/(\d+(?:\.\d+)?)\s*%/);
  if (!m) return null;
  let r = parseFloat(m[1]);
  if (/per\s*month|p\.?\s*m\.?\b/i.test(t)) r *= 12;
  return Math.round(r * 100) / 100;
}

// Resolve a link against the page it was found on. Done by hand because n8n's Code-node
// sandbox does not expose the URL global.
function absoluteUrl(href, base) {
  if (/^https?:\/\//i.test(href)) return href;
  const origin = (base.match(/^https?:\/\/[^/]+/i) || [''])[0];
  if (href.startsWith('//')) return base.split(':')[0] + ':' + href;
  if (href.startsWith('/')) return origin + href;
  return base.replace(/[^/]*$/, '') + href; // relative to the current "directory"
}

function normaliseName(n) {
  n = n.replace(/\s+/g, ' ').trim();
  return /personal loan/i.test(n) ? n : `${n} Personal Loan`;
}

$input.all().forEach((inp, idx) => {
  const { source_site, list_url } = $('Seed sources').itemMatching(idx).json;
  const res = inp.json;
  const html = res && typeof res.data === 'string' ? res.data : '';
  if (!html || html.length < 5000) {
    // Layout/fetch problem: record it and move on, never crash the whole crawl.
    console.log(`[${source_site}] empty/short response (${html.length} bytes) - skipping site`);
    return;
  }

  // Single-lender official site (e.g. bajajfinserv.in): the page IS the product page, there
  // is no table of lenders. Emit one item; "Fetch lender page" re-reads the same URL and the
  // existing eligibility extraction runs unchanged.
  const seed = $('Seed sources').itemMatching(idx).json;
  if (seed.single_product) {
    const plain = text(stripNoise(html));
    const m = plain.match(/rate of interest[^%]{0,80}?(\d+(?:\.\d+)?)\s*%[^.]{0,30}/i) ||
              plain.match(/(\d+(?:\.\d+)?)\s*%\s*p\.?\s*a[^.]{0,20}/i);
    out.push({
      json: {
        source_site, product_name: seed.single_product,
        interest_rate: m ? parseRate(m[0]) : null, rate_text: m ? m[0].trim() : null,
        max_amount_text: null, tenure_text: null, fee_text: null, detail_url: list_url,
      },
    });
    console.log(`[${source_site}] single-product page, rate ${m ? m[0].trim() : 'NOT FOUND'}`);
    return;
  }

  const tables = stripNoise(html).match(/<table[\s\S]*?<\/table>/gi) || [];
  const seen = new Set();
  let count = 0;

  for (const t of tables) {
    const rows = t.match(/<tr[\s\S]*?<\/tr>/gi) || [];
    if (rows.length < 2) continue;
    const header = (rows[0].match(/<t[hd][\s\S]*?<\/t[hd]>/gi) || []).map(text);
    const col = (re) => header.findIndex((h) => re.test(h));
    const cName = col(/^(bank|lender)/i);
    const cRate = col(/interest rate/i);
    if (cName !== 0 || cRate < 0) continue; // not a lender rate table
    const cAmt = col(/(max(imum)? )?loan amount/i);
    const cTen = col(/tenure/i);
    const cFee = col(/processing fee/i);

    for (const r of rows.slice(1)) {
      if (count >= MAX_LENDERS_PER_SITE) break;
      const cellsHtml = r.match(/<t[hd][\s\S]*?<\/t[hd]>/gi) || [];
      if (cellsHtml.length <= cRate) continue;
      const cells = cellsHtml.map(text);
      const name = normaliseName(cells[0]);
      if (!cells[0] || seen.has(name.toLowerCase())) continue;
      const href = (cellsHtml[0].match(/href="([^"]+)"/i) || [])[1];
      const detail_url = href ? absoluteUrl(decode(href), list_url) : null;
      seen.add(name.toLowerCase());
      count++;
      out.push({
        json: {
          source_site,
          product_name: name,
          interest_rate: parseRate(cells[cRate]),
          rate_text: cells[cRate],
          max_amount_text: cAmt >= 0 ? cells[cAmt] || null : null,
          tenure_text: cTen >= 0 ? cells[cTen] || null : null,
          fee_text: cFee >= 0 ? cells[cFee] || null : null,
          detail_url,
        },
      });
    }
  }
  const noLink = out.filter((o) => o.json.source_site === source_site && !o.json.detail_url).length;
  console.log(`[${source_site}] parsed ${count} lenders (${noLink} without a detail link)`);
});

return out;

// n8n Code node: "Extract eligibility text"  (mode: Run Once for All Items)
//
// Input : one item per lender detail page, from "Fetch lender page"
//         (json.data = HTML, or json.error if the fetch failed).
// Output: the lender fields from "Parse lender tables" plus `eligibility_text`
//         (<= ~2.5 KB: just the eligibility prose / key-facts table), so the LLM sees
//         a few hundred tokens instead of an 800 KB page.

const MAX_CHARS = 2500;

const ENT = { amp: '&', nbsp: ' ', quot: '"', apos: "'", lt: '<', gt: '>', rupee: '₹' };
const decode = (s) =>
  s
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&([a-z]+);/gi, (m, n) => (ENT[n.toLowerCase()] !== undefined ? ENT[n.toLowerCase()] : m));
// Block-level tags become sentence breaks so list items don't run together.
const text = (h) =>
  decode(h.replace(/<\/(li|p|tr|div|h[1-6])>|<br\s*\/?>/gi, '. ').replace(/<[^>]+>/g, ' '))
    .replace(/\s+/g, ' ')
    .replace(/(\.\s*){2,}/g, '. ')
    .trim();
const stripNoise = (h) => h.replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, '');

function eligibilityFrom(html) {
  const s = stripNoise(html);
  const chunks = [];

  // (a) key-facts tables, e.g. "Minimum Income Required | Rs.15,000"
  for (const t of s.match(/<table[\s\S]*?<\/table>/gi) || []) {
    for (const r of t.match(/<tr[\s\S]*?<\/tr>/gi) || []) {
      const cells = (r.match(/<t[hd][\s\S]*?<\/t[hd]>/gi) || []).map(text);
      if (cells.length === 2 && /minimum (net )?(monthly )?(income|salary)|min\.? (income|salary)|age limit|cibil|credit score/i.test(cells[0])) {
        chunks.push(`${cells[0]}: ${cells[1]}`);
      }
    }
  }

  // (b) the prose under an "Eligibility" heading (first two matching sections).
  // A section runs until the next heading of the same or higher level, so nested
  // sub-headings ("For salaried", "For self-employed") stay part of it.
  const parts = s.split(/(<h[1-4][^>]*>[\s\S]*?<\/h[1-4]>)/i);
  const level = (h) => parseInt(h.match(/<h([1-4])/i)[1], 10);
  let found = 0;
  for (let i = 1; i < parts.length - 1 && found < 2; i += 2) {
    const heading = text(parts[i]);
    if (!/eligib|who can apply|criteria/i.test(heading)) continue;
    if (/top.?up|calculator|check your|how to/i.test(heading)) continue;
    const L = level(parts[i]);
    let body = text(parts[i + 1]);
    let j = i + 2;
    while (j < parts.length - 1 && level(parts[j]) > L) {
      body += ` ${text(parts[j])}: ${text(parts[j + 1])}`;
      j += 2;
    }
    if (body.length < 40) continue;
    chunks.push(`${heading}: ${body}`);
    found++;
    i = j - 2; // resume after this section
  }
  return chunks.join('\n').slice(0, MAX_CHARS);
}

return $input.all().map((item, i) => {
  const src = $('Parse lender tables').itemMatching(i).json;
  const html = item.json && typeof item.json.data === 'string' ? item.json.data : '';
  const eligibility_text = html ? eligibilityFrom(html) : '';
  if (!eligibility_text) console.log(`no eligibility text for ${src.source_site} / ${src.product_name}`);
  return { json: { ...src, eligibility_text } };
});

// n8n Code node: "Build LLM prompt"
// Attaches the system + user prompt to each lender item. Both the Groq and the Gemini
// request nodes read these fields, so the two providers see the identical prompt.
const SYSTEM = "You extract personal-loan eligibility criteria from text scraped from an Indian lending website.
Return ONLY a JSON object with exactly this shape:
{"rules":[{"employment_types":["Salaried"],"min_income":null,"min_credit_score":null,"min_age":null,"max_age":null}],"qualitative_criteria":null}

Field rules:
- employment_types: array using only "Salaried", "Self-Employed", "Business".
  Salaried employees, government/PSU/defence employees -> "Salaried".
  Self-employed individuals or professionals (doctors, CAs, etc.) -> "Self-Employed".
  Business owners, proprietors, traders, MSMEs -> "Business".
  If the text names no applicant type at all, use all three.
- min_income: MINIMUM MONTHLY net income in INR as an integer. Convert annual figures to monthly (divide by 12). null if not stated.
- min_credit_score: minimum CIBIL / credit score (300-900), only if a number is explicitly stated, otherwise null. Never guess a typical value.
- min_age / max_age: applicant age in years. For max_age use the stated maximum even if it is "at loan maturity". null if not stated.
- If the criteria differ by applicant type (for example a different minimum income for salaried vs self-employed), output one rule per group. Otherwise output exactly ONE rule.
- qualitative_criteria: a short plain-English summary (max 300 characters) of requirements the numeric fields cannot express: work experience, employer category, city/residence, education, existing bank relationship, nationality, business vintage. null if there are none.
- Never invent numbers. When unsure, use null.";

return $input.all().map((item) => ({
  json: {
    ...item.json,
    system_prompt: SYSTEM,
    user_prompt: `Lender: ${item.json.product_name}

Eligibility text:
${item.json.eligibility_text}`,
  },
}));

// n8n Code node: "Validate <provider> output"  (mode: Run Once for All Items)
// One source file; scripts/build_workflows.py stamps PROVIDER in for the Groq and Gemini copies.
//
// Input : raw HTTP responses from the LLM node (or error items if the call failed).
// Output: the original lender item + `valid`, `extraction_status` and, when valid, the
//         normalised fields that go into loan_products.
//
// The LLM is only trusted for *reading the text*. Everything structural is enforced here:
// numeric ranges, employment-type vocabulary, duplicate-rule merging, and the derived
// "envelope" columns used by the Stage 1 SQL pre-filter.

const PROVIDER = 'groq'; // 'groq' | 'gemini'
const TYPES = ['Salaried', 'Self-Employed', 'Business'];

function responseText(res) {
  if (!res || res.error) return null;
  if (PROVIDER === 'groq') return (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || null;
  const parts = res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts;
  return parts ? parts.map((p) => p.text || '').join('') : null;
}

function parseJson(t) {
  if (!t) return null;
  t = t.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) { /* fall through */ }
  const m = t.match(/\{[\s\S]*\}/); // tolerate prose around the object
  if (m) { try { return JSON.parse(m[0]); } catch (e) { /* give up */ } }
  return null;
}

const toInt = (v) => {
  const n = typeof v === 'string' ? parseInt(v.replace(/[,₹\s]|rs\.?/gi, ''), 10) : v;
  return Number.isInteger(n) ? n : null;
};
const inRange = (v, lo, hi) => { const n = toInt(v); return n !== null && n >= lo && n <= hi ? n : null; };

function normType(t) {
  const s = String(t || '').toLowerCase().replace(/[\s_]+/g, '-');
  if (/^salaried|^employee/.test(s)) return 'Salaried';
  if (/^self/.test(s)) return 'Self-Employed';
  if (/^business|^proprietor|^msme|^trader/.test(s)) return 'Business';
  return null;
}

function cleanRule(r) {
  if (!r || typeof r !== 'object') return null;
  let types = (Array.isArray(r.employment_types) ? r.employment_types : []).map(normType).filter(Boolean);
  if (!types.length) types = TYPES.slice(); // text named no applicant type => applies to everyone
  // Indian lenders use "self-employed" to cover business owners too (self-employed
  // professionals AND self-employed non-professionals/businessmen). Our CSV splits them
  // into two categories, so a lender that accepts one accepts the other.
  if (types.includes('Self-Employed') && !types.includes('Business')) types.push('Business');
  const rule = {
    types: [...new Set(types)],
    min_income: inRange(r.min_income, 3000, 1000000), // monthly INR
    min_credit_score: inRange(r.min_credit_score, 300, 900),
    min_age: inRange(r.min_age, 18, 80),
    max_age: inRange(r.max_age, 18, 100),
  };
  if (rule.min_age !== null && rule.max_age !== null && rule.min_age > rule.max_age) {
    rule.min_age = null; rule.max_age = null; // contradictory => don't trust either
  }
  return rule;
}

const minNN = (a) => { const v = a.filter((x) => x !== null); return v.length ? Math.min(...v) : null; };
const maxNN = (a) => { const v = a.filter((x) => x !== null); return v.length ? Math.max(...v) : null; };

// Several rules may cover the same employment type (LLM split by sub-category, or
// repeated itself). Collapse to ONE permissive rule per type, then regroup types that
// ended up identical, so rules never overlap.
function mergeRules(rules) {
  const perType = {};
  for (const t of TYPES) {
    const rs = rules.filter((r) => r.types.includes(t));
    if (!rs.length) continue;
    perType[t] = {
      min_income: minNN(rs.map((r) => r.min_income)),
      min_credit_score: minNN(rs.map((r) => r.min_credit_score)),
      min_age: minNN(rs.map((r) => r.min_age)),
      max_age: maxNN(rs.map((r) => r.max_age)),
    };
  }
  const groups = new Map();
  for (const t of Object.keys(perType)) {
    const k = JSON.stringify(perType[t]);
    if (!groups.has(k)) groups.set(k, { employment_types: [], ...perType[t] });
    groups.get(k).employment_types.push(t);
  }
  return [...groups.values()];
}

// Envelope = a SUPERSET of every rule, so the SQL pre-filter can never drop a user who
// qualifies under any rule. A null in any rule (= unstated) forces the envelope to null.
function envelope(rules) {
  const all = (k) => rules.map((r) => r[k]);
  const anyNull = (k) => all(k).some((v) => v === null);
  return {
    min_income: anyNull('min_income') ? null : Math.min(...all('min_income')),
    min_credit_score: anyNull('min_credit_score') ? null : Math.min(...all('min_credit_score')),
    min_age: anyNull('min_age') ? null : Math.min(...all('min_age')),
    max_age: anyNull('max_age') ? null : Math.max(...all('max_age')),
    allowed_employment_types: TYPES.filter((t) => rules.some((r) => r.employment_types.includes(t))),
  };
}

return $input.all().map((item, i) => {
  const original = $('Build LLM prompt').itemMatching(i).json; // follows paired-item lineage
  const fail = (why) => ({ json: { ...original, valid: false, extraction_status: `invalid_${PROVIDER}`, llm_error: why } });

  if (item.json && item.json.error) return fail(`request failed: ${JSON.stringify(item.json.error).slice(0, 200)}`);
  const parsed = parseJson(responseText(item.json));
  if (!parsed || !Array.isArray(parsed.rules) || parsed.rules.length === 0) return fail('response was not the expected JSON');

  const cleaned = parsed.rules.map(cleanRule).filter(Boolean);
  if (!cleaned.length) return fail('no usable rules');
  const rules = mergeRules(cleaned);

  let q = typeof parsed.qualitative_criteria === 'string' ? parsed.qualitative_criteria.trim() : null;
  if (q && (q.length < 3 || /^(null|none|n\/a)$/i.test(q))) q = null;
  if (q && q.length > 400) q = q.slice(0, 397) + '...';

  return {
    json: {
      ...original,
      valid: true,
      extraction_status: `llm_${PROVIDER}`,
      ...envelope(rules),
      eligibility_rules: rules,
      qualitative_criteria_text: q,
      raw_criteria_text: (original.eligibility_text || '').slice(0, 2000),
    },
  };
});

