// n8n Code node: "Crawl summary"  (runs once, after every upsert has finished)
// Only ancestors of this node can be read with $(...); the skipped/dropped NoOp branches
// are siblings, so derive their counts from ancestors instead.
const hasText = $('Extract eligibility text').all().filter((i) => i.json.eligibility_text);
const totalLenders = $('Extract eligibility text').all().length;
const rows = $input.all().map((i) => i.json);
const by = {};
rows.forEach((r) => { by[r.source_site] = (by[r.source_site] || 0) + 1; });

return [{
  json: {
    upserted_products: rows.length,
    upserted_by_site: by,
    lenders_found: totalLenders,
    skipped_no_eligibility_text: totalLenders - hasText.length,
    dropped_llm_failed: hasText.length - rows.length,
    finished_at: new Date().toISOString(),
  },
}];

// n8n Code node: "Build review prompt"
// One item per (product x employment-type) segment, produced by plan_reviews.sql. The prompt
// carries the lender's fuzzy criteria and source text; no applicant data is needed because
// the model only annotates what the customer still has to check.
const SYSTEM = "You help explain personal-loan eligibility to customers. Applicants have ALREADY been checked against the lender's numeric rules (monthly income, credit score, age) and the employment types the lender accepts. Your job is only to say how confident the match is and, when relevant, what the customer still needs to check.

You receive: the lender product, one applicant employment type, the lender's qualitative requirements (a summary) and the lender's original source text (ground truth).

IMPORTANT: our customer database contains ONLY employment type, monthly income, credit score and age. It has NO information about work experience, employer or employer category, city, education, profession, an existing bank account or relationship, or nationality.

You NEVER reject applicants. Numeric limits and accepted employment types are already decided; do not re-judge them.

Return ONLY a JSON object: {"verdict":"conditional","caveat":"..."}
- verdict "eligible": the qualitative requirements place no extra conditions on this employment type.
- verdict "conditional": the applicant may qualify, but it depends on facts missing from our database (work experience, employer type, city, profession, existing bank relationship, nationality, ...). Name the most important ones in the caveat.
- caveat: one plain-English sentence addressed to the customer, at most 140 characters, no jargon; null when the verdict is "eligible". Only state conditions that appear in the lender's text; never invent a threshold.";

return $input.all().map(({ json: s }) => ({
  json: {
    ...s,
    system_prompt: SYSTEM,
    user_prompt:
      `Lender product: ${s.product_name}
` +
      `Applicant employment type: ${s.employment_type}

` +
      `Lender's qualitative requirements (summary):
${s.qualitative_criteria_text}

` +
      `Lender's source eligibility text (ground truth):
${s.source_text || '(not available)'}`,
  },
}));

